// Secret 7 self-heal: register ops.self_heal.proposed need_hitl.
// Forge opens PR; operator merges. n8n does not patch prod.
// Philanthropy :3002 and OpenClaw :18789 are HOLD — not hard-fail gates.
const body = $json.body || $json;
const correlationId = body.correlationId || body.correlation_id || `self-heal-${Date.now()}`;
const route = body.route || 'unknown';
const statusCode = Number(body.statusCode || body.status_code || 500);
const error = body.error || body.message || 'unknown error';
const stackTrace = body.stackTrace || body.stack || '';
const repo = body.repo || 'n8n-cursor';
const service = body.service || 'hive';
const fixAttempt = Number(body.fix_attempt || body.fixAttempt || 1);
const toolMethod = body.tool_method || body.toolMethod || 'hive_catalog.error_heal';
const businessGoal = body.business_goal || body.businessGoal || 'restore smoke';
const escalate = fixAttempt >= 3;

const text = [
  `SELF-HEAL PROPOSED (Tier 3 merge required)`,
  `cid=${correlationId}`,
  `route=${route} status=${statusCode}`,
  `error=${error}`,
  `repo=${repo} service=${service} attempt=${fixAttempt}`,
  `Forge: branch · patch · test · PR. Operator merges. Do not merge main from n8n.`,
  escalate ? `attempt>=3 → propose hive-creative-pivot (HITL)` : '',
  `Alert Outer Heaven 401 = operator HITL. Do not invent credentials.`
].filter(Boolean).join('\n');

return [{
  json: {
    text,
    correlationId,
    route,
    statusCode,
    error,
    stackTrace,
    repo,
    service,
    fixAttempt,
    toolMethod,
    businessGoal,
    escalate,
    registerPayload: {
      correlationId,
      jobType: 'ops.self_heal.proposed',
      goal: businessGoal,
      source: 'hive-error-heal',
      status: 'need_hitl',
      registerTo: 'scorpion',
      summary: text,
      metadata: {
        lane: 'hive-os',
        route,
        statusCode: String(statusCode),
        repo,
        service,
        fixAttempt: String(fixAttempt),
        toolMethod,
        telegramRequired: 'false',
        outerHeaven401: 'operator-HITL',
        philanthropyHold: 'true',
        openclawHold: 'true'
      }
    }
  }
}];

// Optional Telegram. Missing token or 401 must not fail heal registration.
const token = $env.TELEGRAM_BOT_TOKEN;
const chatId = $env.HIVE_TELEGRAM_CHAT_ID;
if (!token || !chatId || token === 'undefined') {
  return [{
    json: {
      ...$json,
      telegramReady: false,
      telegramHint: 'Telegram optional. Alert Outer Heaven 401 = HITL. Prefer Scorpion / Grok Watchdog.'
    }
  }];
}
return [{ json: { ...$json, telegramReady: true, _telegram: { token, chatId, ready: true } } }];
